function detectSlotFromRuleEditor() {
  const input = document.querySelector(
    '[data-cy="textField_slot-assignment-autocomplete"] input, [data-cy*="slot"] input'
  );
  const raw = input?.value?.trim() ?? "";
  if (!raw) return null;
  const slotName = (raw.includes(">") ? raw.split(">").pop() : raw).trim().toLowerCase();
  for (const slot of Object.values(KONSTRUKTION_SLOTS)) {
    if (slot.name.toLowerCase() === slotName || slotName.includes(slot.name.toLowerCase())) {
      return SLOT_CONTEXTS[slot.id] ?? null;
    }
  }
  return null;
}
function matchModelLabel(text) {
  const t = text.toLowerCase();
  if (t.includes("lamell")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.lamellenEindeckung];
  if (t.includes("solar")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.solarEindeckung];
  if (t.includes("metall") || t.includes("welle") || t.includes("trapez")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.metallEindeckung];
  if (t.includes("glas") || t.includes("poly")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.glasEindeckung];
  if (t.includes("konstruktion") || t.includes("veranda") || t.includes("qubus")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.konstruktion];
  if (t.includes("pfosten") || t.includes("stützstruktur")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.pfosten];
  if (t.includes("rinne") || t.includes("regen")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.regenrinne];
  if (t.includes("schiebetür") || t.includes("schiebetuer")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.schiebetuer];
  if (t.includes("sichtschutz")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.sichtschutzwand];
  if (t.includes("rahmenwand") || t.includes("rahmen") && t.includes("wand")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.rahmenwand];
  if (t.includes("shutter")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.shutters];
  if (t.includes("keil")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.keil];
  if (t.includes("senkrecht")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.senkrechtMarkise];
  if (t.includes("faltmarkise") || t.includes("stoff")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.stoff];
  if (t.includes("markise")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.markise];
  if (t.includes("plissee")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.plissee];
  if (t.includes("led") || t.includes("beleuchtung")) return MODEL_TYPE_CONTEXTS[MODEL_TYPES.led];
  return null;
}
function detectModelBeingEdited() {
  const crumbs = document.querySelectorAll(".MuiBreadcrumbs-ol li, [aria-label='breadcrumb'] li");
  const lastCrumb = crumbs[crumbs.length - 1]?.textContent?.trim() ?? "";
  const heading = document.querySelector("h1, h2")?.textContent?.trim() ?? "";
  const nameInput = document.querySelector("input[name='name']");
  const nameVal = nameInput?.value?.trim() ?? "";
  for (const candidate of [lastCrumb, heading, nameVal]) {
    if (!candidate) continue;
    const ctx = matchModelLabel(candidate);
    if (ctx) return ctx;
  }
  return null;
}
function detectAssistantContext() {
  const dialogTitle = document.querySelector('.MuiDialog-root:not([aria-hidden="true"]) .MuiDialogTitle-root') ?? document.querySelector(".MuiDialog-paper .MuiDialogTitle-root");
  if (dialogTitle) {
    const text = dialogTitle.textContent?.trim() ?? "";
    if (text) {
      const ctx = matchModelLabel(text);
      if (ctx) return ctx;
    }
  }
  const href = window.location.href;
  if (/\/edit\/rules\/\d+/.test(href)) {
    const slotCtx = detectSlotFromRuleEditor();
    if (slotCtx) return slotCtx;
    const crumbs = document.querySelectorAll(".MuiBreadcrumbs-ol li, [aria-label='breadcrumb'] li");
    const ruleName = crumbs[crumbs.length - 1]?.textContent?.trim() ?? "";
    if (ruleName) {
      const ctx = matchModelLabel(ruleName);
      if (ctx) return ctx;
    }
    return SECTION_CONTEXTS["rule-editor"];
  }
  if (/\/edit\/models\/\d+/.test(href)) {
    return detectModelBeingEdited() ?? SECTION_CONTEXTS["models"];
  }
  if (href.includes("/edit/rule") || !!document.querySelector("[data-cy='rules-toolbar-all-buttons-action-option-addActionRule']")) {
    return SECTION_CONTEXTS["rules-list"];
  }
  if (href.includes("/edit/model") || !!document.querySelector("[data-cy='models-toolbar']")) {
    return SECTION_CONTEXTS["models"];
  }
  if (href.includes("/edit/feature")) return SECTION_CONTEXTS["features"];
  if (href.includes("/edit/material")) return SECTION_CONTEXTS["materials"];
  if (href.includes("/edit/preview") || href.includes("/configurator")) return SECTION_CONTEXTS["preview"];
  if (href.includes("/edit/settings/plugin")) return SECTION_CONTEXTS["plugin-settings"];
  return FALLBACK_CONTEXT;
}

